package leetcode.medium;

import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;

import static org.junit.Assert.*;

@RunWith(JUnit4.class)
public class OnlineStockSpanTest {

    @Test
    public void nextTest() {
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        assertEquals(0, stockSpan.next(10));
        assertEquals(1, stockSpan.next(20));
        assertEquals(1, stockSpan.next(30));
    }

    @Test
    public void calculateSpansTest() {
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        int[] prices = {10, 20, 30};
        int[] spans = stockSpan.calculateSpans(prices);
        assertArrayEquals(new int[]{0, 1, 1}, spans);
    }

}
```

This code tests the `next()` and `calculateSpans()` methods of the `OnlineStockSpan` class. The `next()` method is tested with three prices, 10, 20, and 30, and the expected values are 0, 1, and 1 respectively. The `calculateSpans()` method is tested with an array of prices, {10, 20, 30}, and the expected spans are {0, 1, 1}.
